using System;
using System.Drawing;
using System.IO;

namespace HarnessProfileSwitcher.UI
{
    internal static class BrandAssets
    {
        private static Image logo;
        private static Icon windowIcon;

        public static Image Logo()
        {
            if (logo == null) logo = Image.FromStream(new MemoryStream(Convert.FromBase64String(LogoBase64)));
            return logo;
        }

        public static Icon WindowIcon()
        {
            if (windowIcon == null) windowIcon = new Icon(new MemoryStream(Convert.FromBase64String(IconBase64)));
            return windowIcon;
        }

        private const string LogoBase64 = "";

        private const string IconBase64 = "";
    }
}
